function tgc_out(array $d,int $s=200): never {http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function tgc_can(array $u): bool {if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Approve',$p,true)||in_array('Edit',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Approve',$a,true)||in_array('Edit',$a,true)))return true;return false;}
function tgc_defaults(): array {return ['revision'=>0,'journals'=>[],'bankAccountSettings'=>[],'exportCandidates'=>[],'tgBankTransactions'=>[],'tgLiabilities'=>[],'tgYearEndRevaluations'=>[]];}
function tgc_read(): array {tt_ensure_data_dir();if(!is_file(TT_TGC_FILE))return tgc_defaults();$h=fopen(TT_TGC_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(tgc_defaults(),$v):tgc_defaults();}
function tgc_catalog(): array {$raw=file_get_contents(TT_TGC_MASTER);$m=$raw?json_decode($raw,true):null;if(!is_array($m))throw new RuntimeException('Accounting master unavailable.');$o=[];foreach((array)($m['chart']??[]) as $a)if(is_array($a)&&isset($a['code']))$o[(string)$a['code']]=$a;return $o;}
function tgc_line(string $a,float $dr,float $cr,array $cat,array $x=[]): array {if(!isset($cat[$a]))tgc_out(['ok'=>false,'error'=>'Approved account '.$a.' unavailable.'],422);return array_merge(['account'=>$a,'accountName'=>(string)($cat[$a]['name']??$a),'debit'=>round($dr,2),'credit'=>round($cr,2)],$x);}
function tgc_rates(string $date): array {$m=(array)(tt_read_store()['masters']??[]);$best=null;foreach((array)($m[TT_TGC_RATE_TYPE]??[]) as $r){if(!is_array($r))continue;$v=array_values((array)($r['values']??[]));while(count($v)<12)$v[]='';$st=strtolower((string)$v[10]);if(str_contains($st,'inactive')||str_contains($st,'historical'))continue;$from=(string)$v[6];$to=(string)$v[7];if($from!==''&&$date<$from)continue;if($to!==''&&$date>$to)continue;if($best===null||$from>(string)$best['effectiveFrom'])$best=['id'=>(string)($r['id']??''),'code'=>(string)$v[1],'sellUsdToAed'=>(float)$v[3],'buyUsdWithAed'=>(float)$v[4],'closingTax'=>(float)$v[5],'effectiveFrom'=>$from,'effectiveTo'=>$to,'yearEnd'=>(string)$v[8],'closingCurrency'=>(string)$v[9]];}if(!$best)tgc_out(['ok'=>false,'error'=>'No active TG Master rate applies to this date.'],422);return $best;}
function tgc_tg_bank_rows(array $store): array {$m=(array)(tt_read_store()['masters']??[]);$out=[];foreach((array)($m['banks']??[]) as $r){if(!is_array($r))continue;$v=array_values((array)($r['values']??[]));while(count($v)<14)$v[]='';$linked=strtoupper((string)$v[1]);if(!str_contains($linked,'TG')&&!str_contains($linked,'TRANS GRAINS'))continue;$id=(string)($r['id']??'');$s=is_array($store['bankAccountSettings'][$id]??null)?$store['bankAccountSettings'][$id]:[];if(empty($s['active'])||strtoupper((string)$v[7])!=='USD')continue;$out[$id]=['id'=>$id,'bank'=>(string)$v[4],'title'=>(string)$v[3],'currency'=>'USD'];}return $out;}
function tgc_bank_asof(array $store,string $id,string $date): array {$native=0.0;$aed=0.0;foreach((array)($store['journals']??[]) as $j){if(!is_array($j)||($j['status']??'')!=='Posted'||($j['entity']??'')!=='TG'||(string)($j['date']??'')>$date)continue;$jm=is_array($j['meta']??null)?$j['meta']:[];foreach((array)($j['lines']??[]) as $l){if(!is_array($l)||(string)($l['account']??'')!=='1110')continue;$bid=(string)($l['bankAccountId']??$jm['bankAccountId']??'');if($bid!==$id)continue;$native+=(float)($l['bankDebit']??0)-(float)($l['bankCredit']??0);$aed+=(float)($l['debit']??0)-(float)($l['credit']??0);}}return ['native'=>round($native,4),'carryingAed'=>round($aed,2),'carryingRate'=>$native>0?round($aed/$native,8):0.0];}
function tgc_receipt_used_asof(array $store,string $candidateId,string $date): float {$n=0.0;foreach((array)($store['tgBankTransactions']??[]) as $x){if(!is_array($x)||($x['kind']??'')!=='Receipt'||($x['receiptType']??'')!=='EXPORT_RECEIVABLE'||(string)($x['date']??'')>$date||(string)($x['sourceCandidateId']??'')!==$candidateId)continue;$n+=(float)($x['settlementAmountNative']??0);}return round($n,4);}
function tgc_liability_paid_asof(array $store,string $liabilityId,string $date): float {$n=0.0;foreach((array)($store['tgBankTransactions']??[]) as $x){if(!is_array($x)||($x['kind']??'')!=='Payment'||(string)($x['date']??'')>$date||(string)($x['sourceLiabilityId']??'')!==$liabilityId)continue;$n+=(float)($x['amountNative']??0);}return round($n,4);}
function tgc_historical_rate(array $store,string $kind,string $id,float $base,string $date): float {$rate=$base;$best='';foreach((array)($store['tgYearEndRevaluations']??[]) as $r){if(!is_array($r))continue;$rd=(string)($r['date']??'');if($rd===''||$rd>$date||$rd<$best)continue;$items=$kind==='receivable'?(array)($r['receivableItems']??[]):(array)($r['liabilityItems']??[]);foreach($items as $x){if(!is_array($x))continue;$key=$kind==='receivable'?(string)($x['candidateId']??''):(string)($x['liabilityId']??'');if($key===$id){$rate=(float)($r['closingRate']??$x['closingRate']??$rate);$best=$rd;break;}}}return $rate;}
function tgc_receivables_asof(array $store,string $date,float $closingRate): array {$rows=[];foreach((array)($store['exportCandidates']??[]) as $c){if(!is_array($c)||($c['entity']??'')!=='TG'||($c['candidateType']??'')!=='CUSTOMER_EXPORT_SALE'||empty($c['journalId']))continue;$recognition=(string)($c['recognitionDate']??$c['suggestedRecognitionDate']??'');if($recognition!==''&&$recognition>$date)continue;if(strtoupper((string)($c['transactionCurrency']??''))!=='USD')continue;$orig=(float)($c['transactionAmount']??0);$used=tgc_receipt_used_asof($store,(string)$c['id'],$date);$open=round($orig-$used,4);if($open<=.0001)continue;$base=(float)($c['functionalRate']??0);$rate=tgc_historical_rate($store,'receivable',(string)$c['id'],$base,$date);if($rate<=0)continue;$carrying=round($open*$rate,2);$target=round($open*$closingRate,2);$adj=round($target-$carrying,2);$m=is_array($c['meta']??null)?$c['meta']:[];$rows[]=['candidateId'=>(string)$c['id'],'reference'=>(string)($c['reference']??$c['sourceKey']??''),'customer'=>(string)($m['customer']??''),'outstandingUsd'=>$open,'carryingRate'=>$rate,'carryingAed'=>$carrying,'closingRate'=>$closingRate,'targetAed'=>$target,'adjustmentAed'=>$adj];}usort($rows,static fn($a,$b)=>strcmp((string)$a['reference'],(string)$b['reference']));return $rows;}
function tgc_liabilities_asof(array $store,string $date,float $closingRate): array {$rows=[];
