 usort($rows,static fn($a,$b)=>strcmp((string)$a['counterparty'],(string)$b['counterparty'])?:strcmp((string)$a['reference'],(string)$b['reference']));return $rows;}
function tgc_preview(array $store,string $date): array {$rates=tgc_rates($date);$mmdd=substr($date,5,5);$yearEnd=(string)($rates['yearEnd']??'12-31');$rate=(float)$rates['closingTax'];$banks=[];foreach(tgc_tg_bank_rows($store) as $id=>$b){$bal=tgc_bank_asof($store,$id,$date);if(abs((float)$bal['native'])<.0001&&abs((float)$bal['carryingAed'])<.01)continue;$target=round((float)$bal['native']*$rate,2);$banks[]=array_merge($b,$bal,['closingRate'=>$rate,'targetAed'=>$target,'adjustmentAed'=>round($target-(float)$bal['carryingAed'],2)]);}usort($banks,static fn($a,$b)=>strcmp((string)$a['bank'],(string)$b['bank']));$receivables=tgc_receivables_asof($store,$date,$rate);$liabilities=tgc_liabilities_asof($store,$date,$rate);$assetAdj=round(array_sum(array_column($banks,'adjustmentAed'))+array_sum(array_column($receivables,'adjustmentAed')),2);$liabilityAdj=round(array_sum(array_column($liabilities,'adjustmentAed')),2);$net=round($assetAdj-$liabilityAdj,2);$existing=null;foreach((array)($store['tgYearEndRevaluations']??[]) as $x)if(is_array($x)&&(string)($x['date']??'')===$date){$existing=$x;break;}$today=(new DateTimeImmutable('now',new DateTimeZone('Asia/Dubai')))->format('Y-m-d');return ['ok'=>true,'date'=>$date,'yearEnd'=>$yearEnd,'isYearEndDate'=>$mmdd===$yearEnd,'isFuture'=>$date>$today,'rates'=>$rates,'banks'=>$banks,'receivables'=>$receivables,'liabilities'=>$liabilities,'assetAdjustmentAed'=>$assetAdj,'liabilityAdjustmentAed'=>$liabilityAdj,'netMonetaryAdjustmentAed'=>$net,'estimatedFxEffect'=>$net>0?['direction'=>'Gain','amount'=>abs($net)]:($net<0?['direction'=>'Loss','amount'=>abs($net)]:['direction'=>'Nil','amount'=>0]),'existing'=>$existing,'limitations'=>['This routine remeasures supported TG USD monetary assets and liabilities: active TG USD banks, open recognized TG USD export receivables, TG USD supplier/service liabilities and recognized TG↔Pakistan USD intercompany payables.','Native USD balances do not change during revaluation; only the AED carrying valu